-- TỰ SINH bằng `npm run seed:chuong-trinh` từ src/data/chuong-trinh.json. Không sửa tay.
do $seed$
declare v_to uuid; v_cd uuid; v_nh uuid; v_tuan uuid;
begin
  select id into v_to from public.to_chuyen_mon where ten = 'Tổ 5–6 tuổi, Trường MN Võ Cường' limit 1;
  if v_to is null then insert into public.to_chuyen_mon (ten) values ('Tổ 5–6 tuổi, Trường MN Võ Cường') returning id into v_to; end if;
  if exists (select 1 from public.chu_de where to_id = v_to and ten = 'Nghề nghiệp') then return; end if;
end $seed$;
